const s = wb.getWorksheet('Data');
const out:any[] = [];
for (const a of ['D1','E1','F1','G1','H1','D2','E2','F2','G2','H2','H78']) { const c = s.getRange(a).getCell(); out.push([a, c.getFormula?.(), c.getStyle().getNumberFormat?.(), c.getStyle().getFont?.().getBold?.()]); }
log(JSON.stringify(out));
const v = s.getRange('D2:G78').getValues();
const f = s.getRange('H2:H78').getFormulas?.();
log(JSON.stringify(f?.slice(0,3)));
const odd:any[]=[];
const rows = v.map((r:any[],i:number)=>{ const e=String(r[1]).replace(/[^\d.-]/g,''), g=String(r[3]).replace(/[^\d.-]/g,''); const d=String(r[0]).replace(/[^\d\/]/g,'').split('/'); if(d.length!==3||+d[0]!==+e||+d[1]!==+r[2]||+d[2]!==+g||typeof r[2]!=='number') odd.push([i+2,JSON.stringify(r)]); return [i+2,r[0],r[1],r[2],r[3]];});
log('odd',JSON.stringify(odd));
log(JSON.stringify(v.map((r:any[])=>String(r[0]).replace(/[^\d\/]/g,''))));
log(JSON.stringify([...String(v[0][1])].map(c=>c.charCodeAt(0))), JSON.stringify([...String(v[0][3])].map(c=>c.charCodeAt(0))));

